def binary_search(items, target):
    """Return the index of target in the sorted list items, or -1 if absent."""
    low, high = 0, len(items) - 1
    while low <= high:
        mid = (low + high) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            low = mid + 1      # target can only be in the right half
        else:
            high = mid - 1     # target can only be in the left half
    return -1

print(binary_search([2, 5, 8, 12, 16, 23, 38, 56, 72], 23))  # 5

function binarySearch(items, target) {
  let low = 0;
  let high = items.length - 1;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    if (items[mid] === target) return mid;
    if (items[mid] < target) low = mid + 1;
    else high = mid - 1;
  }
  return -1;
}

