public class BinarySearch {
    static int binarySearch(int[] items, int target) {
        int low = 0;
        int high = items.length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2; // avoids int overflow of (low + high)
            if (items[mid] == target) return mid;
            if (items[mid] < target) low = mid + 1;
            else high = mid - 1;
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] items = {2, 5, 8, 12, 16, 23, 38, 56, 72};
        System.out.println(binarySearch(items, 23)); // 5
    }
}

#include <iostream>
#include <vector>

int binarySearch(const std::vector<int>& items, int target) {
    int low = 0;
    int high = static_cast<int>(items.size()) - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;  // avoids overflow of (low + high)
        if (items[mid] == target) return mid;
        if (items[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> items{2, 5, 8, 12, 16, 23, 38, 56, 72};
    std::cout << binarySearch(items, 23) << "\n";  // 5
}
